export const SAMPLE_RATE=48e3,cancelled=()=>new DOMException("Simulation preparation cancelled.","AbortError");export function check(n){if(n?.aborted)throw cancelled()}const h=48e3;function A(n,u){const r=u%1;return n==="square"?(r<.5?1:-1)*.5:n==="tri"?1-4*Math.abs(r-.5):n==="saw"?r*2-1:Math.sin(u*Math.PI*2)}function w(n,u,r,p,o,b,c="sine",d=.004,M=1){const t=Math.round(u*h),e=Math.round(r*h);let i=0;for(let a=0;a<e&&t+a<n.length&&t+a>=0;a++){const l=a/h,s=a/e,m=p+(o-p)*s,y=Math.min(1,l/d)*Math.pow(1-s,M);i+=m/h,n[t+a]+=b*y*A(c,i)}}function E(n,u,r,p,o=.2,b=1.5,c=1){const d=Math.round(u*h),M=Math.round(r*h);let t=0,e=c>>>0||1;for(let i=0;i<M&&d+i<n.length&&d+i>=0;i++){e=e*1664525+1013904223>>>0;const a=e/4294967296*2-1;t+=o*(a-t);const l=i/M;n[d+i]+=p*Math.pow(1-l,b)*t}}const v=[1,1.1225,1.2599,1.4983];export function voice(n){return n==="arcade"?{osc:"square",gain:.8,pitch:1.25,lp:.4,body:150,tick:.05}:n==="soft"?{osc:"sine",gain:.6,pitch:.85,lp:.08,body:130,tick:.07}:n==="wood"?{osc:"tri",gain:.95,pitch:.62,lp:.16,body:105,tick:.045}:{osc:"tri",gain:.85,pitch:1,lp:.25,body:170,tick:.04}}export async function synthesize(n,u,r,{signal:p}={}){if(check(p),!r.sound||r.volume===0)return null;const o=new Float32Array(Math.max(1,Math.round(u*h))),b=r.volume/100*1.2,c=voice(r.soundSet),d=new Map;for(let t=0;t<n.length;t++){t%48===0&&(await new Promise(y=>setTimeout(y,0)),check(p));const e=n[t],i=`${e.type}:${e.player??0}`;if(e.t-(d.get(i)??-10)<.03)continue;d.set(i,e.t);const a=e.t,l=b*c.gain,s=c.pitch,m=v[(e.player??0)%4];switch(e.type){case"count":w(o,a,.14,660*s,660*s,.2*l,c.osc,.003,1.5);break;case"go":w(o,a,.3,520*s,1040*s,.22*l,c.osc,.01,1.3);break;case"move":{const y=(e.fast?.6:1)*l;w(o,a,c.tick,(e.jump?1500:1040)*s*m,(e.jump?900:700)*s*m,.3*y,c.osc,.0015,1.8),E(o,a,.022,.1*y,.55,2.2,e.id+3);break}case"wall":E(o,a,.07,.42*l,c.lp,1.7,e.id+5),w(o,a,.1,c.body*1.5,c.body*.62,.36*l,"sine",.0015,1.6),w(o,a+.004,.035,620*s,280*s,.12*l,c.osc,.0015,2.2);break;case"win":{[659.25,783.99,1046.5].forEach((f,k)=>{const g=a+k*.085,x=k===2?.62:.16;w(o,g,x,f*s,f*s,.2*l,c.osc,.004,1.25),w(o,g,x,f*s*2,f*s*2,.05*l,"sine",.004,1.4)});break}}}for(let t=0;t<o.length;t++)o[t]=Math.tanh(o[t]*1.2);const M=Math.min(o.length,Math.round(.002*h));for(let t=0;t<M;t++)o[o.length-1-t]*=t/M;return check(p),{samples:o,sampleRate:h}}
